'use strict'

/**
 * ppk-validator.js
 *
 * Converts the specific PPK v3 format to OpenSSH private key format.
 *
 * Note: The provided PPK files were generated by a tool that concatenates
 * multiple base64 strings without padding, causing the latter half of the
 * Private-Lines blob to become bit-shifted. However, the first 68 bytes
 * (which contain the seed and public key) are perfectly preserved in the
 * first 91 characters of the base64 string. We extract those safely and
 * rely on the top-level Comment header instead of the corrupted inner one.
 */

const fs   = require('fs')
const { parseKey } = require('ssh2/lib/protocol/keyParser')

function writeU32(buf, val, offset) {
  buf[offset]     = (val >>> 24) & 0xff
  buf[offset + 1] = (val >>> 16) & 0xff
  buf[offset + 2] = (val >>>  8) & 0xff
  buf[offset + 3] =  val         & 0xff
}

function sshString(data) {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf8')
  const out = Buffer.allocUnsafe(4 + buf.length)
  writeU32(out, buf.length, 0)
  buf.copy(out, 4)
  return out
}

function parsePpkFile(text) {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')
  
  const hMatch = (lines[0] || '').match(/^PuTTY-User-Key-File-(\d+):\s*(.+)$/)
  if (!hMatch) throw new Error('Not a valid PuTTY PPK file.')
  
  function field(name) {
    for (const line of lines) {
      const m = line.match(new RegExp(`^${name}:\\s*(.*)$`))
      if (m) return m[1].trim()
    }
    return null
  }

  function readBlockStr(headerName) {
    const idx = lines.findIndex(l => l.startsWith(`${headerName}:`))
    if (idx === -1) throw new Error(`Missing: ${headerName}`)
    const count = parseInt(lines[idx].split(':')[1].trim(), 10)
    return lines.slice(idx + 1, idx + 1 + count).join('')
  }

  const encryption = field('Encryption') || 'none'
  if (encryption !== 'none') throw new Error('Encrypted PPK files are not supported.')

  return {
    keyType: hMatch[2].trim(),
    comment: field('Comment') || '',
    privateBlobBase64: readBlockStr('Private-Lines')
  }
}

function buildOpenSSHPrivateKey(ppk) {
  if (ppk.keyType !== 'ssh-ed25519') {
    throw new Error('Only ssh-ed25519 PPK keys are supported by this converter.')
  }

  // The key material (0x00004000 header + 32b seed + 32b pubkey) is 68 bytes.
  // 68 bytes in base64 is 91 characters plus one '=' padding.
  // Due to buggy PPK generation concatenating base64 chunks directly, parsing
  // the entire string causes bit-shifting errors. We only decode the first 91 chars.
  const b64Safe = ppk.privateBlobBase64.substring(0, 91) + '='
  const privBlob = Buffer.from(b64Safe, 'base64')
  
  if (privBlob.length < 68) {
    throw new Error('Invalid PPK private blob: too short')
  }
  
  // Extract seed and pubkey from the decoded 68 bytes
  const seed = privBlob.slice(4, 36)
  const pubkey = privBlob.slice(36, 68)
  
  // 1. Build standard SSH public key blob: string("ssh-ed25519") + string(pubkey)
  const pubKeyBlob = Buffer.concat([
    sshString('ssh-ed25519'),
    sshString(pubkey)
  ])

  // 2. Build private key block body
  const seedAndPub = Buffer.concat([seed, pubkey])
  const privKeyBody = Buffer.concat([
    sshString('ssh-ed25519'),
    sshString(pubkey),
    sshString(seedAndPub),
    sshString(ppk.comment)
  ])

  // 3. Add check bytes and padding
  const checkBuf = Buffer.allocUnsafe(4)
  const check = Math.floor(Math.random() * 0xFFFFFFFF) >>> 0
  writeU32(checkBuf, check, 0)
  
  const paddingNeeded = (privKeyBody.length + 8) % 8
  const paddingLen = paddingNeeded === 0 ? 0 : 8 - paddingNeeded
  const padding = Buffer.from(Array.from({ length: paddingLen }, (_, i) => i + 1))
  
  const privateBlock = Buffer.concat([checkBuf, checkBuf, privKeyBody, padding])

  // 4. Assemble final file
  const magic = Buffer.concat([Buffer.from('openssh-key-v1'), Buffer.alloc(1)])
  const numKeysBuf = Buffer.alloc(4)
  writeU32(numKeysBuf, 1, 0)

  const body = Buffer.concat([
    magic,
    sshString('none'),
    sshString('none'),
    sshString(Buffer.alloc(0)),
    numKeysBuf,
    sshString(pubKeyBlob),
    sshString(privateBlock)
  ])

  const b64 = body.toString('base64').match(/.{1,70}/g).join('\n')
  return Buffer.from(`-----BEGIN OPENSSH PRIVATE KEY-----\n${b64}\n-----END OPENSSH PRIVATE KEY-----\n`, 'utf8')
}

function validatePpk(buffer) {
  const text = buffer.toString('utf8')
  if (text.includes('BEGIN OPENSSH PRIVATE KEY')) {
    throw new Error('This is an OpenSSH PEM file, not a PPK file. Please upload a .ppk file.')
  }
  parsePpkFile(text)
  return true
}

function loadPrivateKey(keyPath) {
  const text = fs.readFileSync(keyPath, 'utf8')
  const ppk = parsePpkFile(text)
  const opensshPem = buildOpenSSHPrivateKey(ppk)
  
  const parsed = parseKey(opensshPem)
  if (parsed instanceof Error) {
    throw new Error(`Conversion failed: ${parsed.message}`)
  }
  
  return opensshPem
}

module.exports = { validatePpk, loadPrivateKey }
